select pg_temp.recusa($t$update public.produtos set bling_id='999' where loja_id='eb000000-0000-0000-0000-000000000001'$t$,'mudança de identidade bloqueada');
select pg_temp.recusa($t$update public.produtos set loja_id='eb000000-0000-0000-0000-000000000001' where loja_id='eb000000-0000-0000-0000-000000000002'$t$,'movimento para loja protegida bloqueado');
